router5.get("/transactions/detailed", async (c) => {
  try {
    const startDate = c.req.query("startDate");
    const endDate = c.req.query("endDate");
    const month = c.req.query("month");
    const year = c.req.query("year");
    let matchStage = {};
    if (startDate && endDate) {
      matchStage.created_at = {
        $gte: new Date(startDate),
        $lte: /* @__PURE__ */ new Date(endDate + "T23:59:59.999Z")
      };
    } else if (month && year) {
      const m2 = parseInt(month) - 1;
      const y = parseInt(year);
      const startOfMonth = new Date(y, m2, 1);
      const endOfMonth = new Date(y, m2 + 1, 0, 23, 59, 59, 999);
      matchStage.created_at = {
        $gte: startOfMonth,
        $lte: endOfMonth
      };
    }
    const invoices = await models_default.Invoice.find(matchStage).sort({ created_at: -1 }).populate({
      path: "order_id",
      populate: { path: "distributor_id" }
    }).lean();
    const transactions = invoices.map((inv) => {
      const user = inv.order_id?.distributor_id || {};
      return {
        date: inv.created_at.toISOString().split("T")[0],
        invoice_number: inv.invoice_number,
        firm_name: user.firm_name,
        town: user.address,
        taxable_amount: inv.subtotal || 0,
        gst_amount: (inv.cgst_amount || 0) + (inv.sgst_amount || 0),
        total_amount: inv.grand_total || 0
      };
    });
    return c.json(transactions);
  } catch (err) {
    console.error(err);
    return c.json({ message: "Server Error" }, 500);
  }
});
