router7.put("/:id", async (c) => {
  try {
    const user_id = c.req.param("id");
    const body = await c.req.parseBody();
    const { firm_name, gst_number, address, phone_number, owner_name, fssai_number, password, rate_type, rate_version, deletePan, deleteAadhar, deletePhoto } = body;
    const query = getQueryId3(user_id, "sql_user_id");
    const user = await models_default.User.findOne({ ...query, role: { $in: ["DISTRIBUTOR", "ND", "OFFLINE_CLIENT"] } });
    if (!user)
      return c.json({ message: "Distributor not found" }, 404);
    if (phone_number !== user.phone_number) {
      const existing = await models_default.User.findOne({ phone_number });
      if (existing) {
        return c.json({ message: "Phone number already registered" }, 400);
      }
    }
    user.firm_name = firm_name;
    user.gst_number = gst_number;
    user.address = address;
    user.phone_number = phone_number;
    user.owner_name = owner_name;
    user.fssai_number = fssai_number;
    user.rate_type = rate_type || user.rate_type;
    user.rate_version = rate_version || user.rate_version;
    if (password) {
      const salt = await bcryptjs_default.genSalt(10);
      user.password_hash = await bcryptjs_default.hash(password, salt);
    }
    const panFile = body["panFile"];
    const aadharFile = body["aadharFile"];
    const photoFile = body["photoFile"];
    if (panFile) {
      user.pan_card = Buffer.from(await panFile.arrayBuffer());
    } else if (deletePan === "true") {
      user.pan_card = null;
    }
    if (aadharFile) {
      user.aadhar_card = Buffer.from(await aadharFile.arrayBuffer());
    } else if (deleteAadhar === "true") {
      user.aadhar_card = null;
    }
    if (photoFile) {
      user.photo = Buffer.from(await photoFile.arrayBuffer());
    } else if (deletePhoto === "true") {
      user.photo = null;
    }
    await user.save();
    return c.json({ message: "Distributor updated successfully" });
  } catch (err) {
    console.error(err);
    return c.json({ message: "Failed to update distributor" }, 500);
  }
});
