router10.get("/credit-note/:cn_id/download", async (c) => {
  try {
    const cnQuery = getQueryId5(c.req.param("cn_id"), "sql_credit_note_id");
    const cn = await models_default.CreditNote.findOne(cnQuery).populate("distributor_id").populate({
      path: "items.variant_id",
      populate: { path: "product_id" }
    });
    if (!cn)
      return c.json({ message: "Credit Note not found" }, 404);
    const user = cn.distributor_id || {};
    const settings = await models_default.CompanySettings.findOne() || {};
    const cnData = {
      credit_note: {
        credit_note_id: cn.sql_credit_note_id || cn._id.toString(),
        credit_note_number: cn.cn_number,
        total_amount: cn.total_amount,
        reason: cn.reason,
        created_at: cn.created_at,
        is_paid_out: cn.is_paid_out
      },
      items: cn.items.map((i) => {
        const variant = i.variant_id || {};
        const product = variant.product_id || {};
        return {
          product_name: product.name || "Unknown",
          pack_size: variant.pack_size || "-",
          reason: i.reason,
          quantity: i.quantity,
          price_at_order: i.price_at_order,
          item_total: i.item_total
        };
      })
    };
    const pdfUrl = await generateCreditNotePdf(cnData, user, settings, c.env.MY_BUCKET);
    cn.pdf_url = pdfUrl;
    await cn.save();
    const file = await c.env.MY_BUCKET.get(pdfUrl);
    if (!file) {
      return c.json({ message: "File not found on server" }, 404);
    }
    c.header("Content-Type", "application/pdf");
    c.header("Content-Disposition", `attachment; filename="CN_${cn.cn_number}.pdf"`);
    return c.body(file.body);
  } catch (err) {
    console.error(err);
    return c.json({ message: "Failed to generate CN PDF" }, 500);
  }
});
